"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["10283"],{43882(e,t,a){a.r(t),a.d(t,{metadata:()=>o,default:()=>g,frontMatter:()=>s,contentTitle:()=>i,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"qiangguo/applaudforshfl","title":"","description":"Two weeks ago, Shang Fulin spoke \\"Now that\'s a real man. Good on you, Shandong man. It\'s decided. Absolutely do not pay any attention to the clamoring of those with ulterior motives.\\" Recently, seeing this Shandong man getting more and more on the right track, I\'m giving Shang Fulin another round of applause.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/applaudforshfl.md","sourceDirName":"qiangguo","slug":"/qiangguo/applaudforshfl","permalink":"/en/qiangguo/applaudforshfl","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"applaudforshfl","title":"","hide_table_of_contents":true,"sidebar_label":"Applauding Shang Fulin \u2014 A Regulator Who Can\'t Provoke Interest Warfare Among All Parties Is Not a Good Regulator (2005-6-20)"},"sidebar":"qiangguoSidebar","previous":{"title":"Your Bodies and Names Shall Perish, Yet Rivers Flow On Forever \u2014 Confucianism Constitutes the True \\"Greater East Asia Co-Prosperity Sphere\\" in Thought","permalink":"/en/qiangguo/confucianism"},"next":{"title":"Applauding Shang Fulin \u2014 Those Attempting to Blackmail the Government Using the Share Structure Reform Issue Must Be Legally Sanctioned (2005-5-16)","permalink":"/en/qiangguo/applaudforshfl2"}}'),n=a(74848),r=a(28453);let s={id:"applaudforshfl",title:"",hide_table_of_contents:!0,sidebar_label:"Applauding Shang Fulin \u2014 A Regulator Who Can't Provoke Interest Warfare Among All Parties Is Not a Good Regulator (2005-6-20)"},i="Applause for Shang Fulin \u2014 A Regulator Who Can't Provoke Interest Wars Is Not a Good Regulator (2005-6-20)",l={},h=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"applause-for-shang-fulin--a-regulator-who-cant-provoke-interest-wars-is-not-a-good-regulator-2005-6-20",children:"Applause for Shang Fulin \u2014 A Regulator Who Can't Provoke Interest Wars Is Not a Good Regulator (2005-6-20)"})}),"\n",(0,n.jsx)(t.p,{children:'Two weeks ago, Shang Fulin spoke: "The split share structure reform is an arrow that has left the bow\u2014there is no turning back." I gave my first round of applause: "Now that\'s a real man. Good on you, Shandong man. It\'s decided. Absolutely do not pay any attention to the clamoring of those with ulterior motives." Recently, seeing this Shandong man getting more and more on the right track, I\'m giving Shang Fulin another round of applause.'}),"\n",(0,n.jsx)(t.p,{children:"A good regulator, or market maker, absolutely must not put the risk on their own head. Knowing how to transfer risk and letting various interest parties wage war against each other to reach equilibrium\u2014that is the proper path. A regulator who can't provoke wars between various interests is not a good regulator. No market exists that doesn't need regulation, and a market without a good regulator or market maker can only be a garbage market."}),"\n",(0,n.jsx)(t.p,{children:"The most correct move by Shang Fulin was handing the decision-making power to the shareholders themselves, rather than making a one-size-fits-all decision himself. So-called shareholders represent the interests of all parties. Let them fight it out amongst themselves. Never sympathize with anyone in the market\u2014everyone who enters the market comes out of greed, and none deserve sympathy. If you want to sympathize with someone, you'd be better off sympathizing with those people in remote mountain villages."}),"\n",(0,n.jsx)(t.p,{children:"Everything in the market is theater. The bears have their script, the bulls have theirs\u2014it's all just for profit. Whether Huang Gai beats Zhou Yu or Zhou Yu beats Huang Gai, it's all with purpose. A regulator simply should not care about these people. Even if they stage a suicidal jump from a building, don't care. There are plenty of people\u2014what's the problem if a couple die?"}),"\n",(0,n.jsx)(t.p,{children:"Markets always have problems\u2014if not this, then that\u2014and market greed is infinite. Don't let the market push you around."})]})}function g(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(u,{...e})}):u(e)}},28453(e,t,a){a.d(t,{R:()=>s,x:()=>i});var o=a(96540);let n={},r=o.createContext(n);function s(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);